    /**
     * Method to retrieve the Aircraft via AircraftFetchOneSummary
     * @param 	summary AircraftFetchOneSummary 
     * @return 	AircraftFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Aircraft getAircraft( AircraftFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "AircraftFetchOneSummary arg cannot be null" );
    	
    	Aircraft entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Aircraft
        	// --------------------------------------
        	CompletableFuture<Aircraft> futureEntity = queryGateway.query(new FindAircraftQuery( new LoadAircraftFilter( summary.getAircraftId() ) ), ResponseTypes.instanceOf(Aircraft.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Aircraft with id " + summary.getAircraftId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


